-- SUHAS.COM initial marketplace schema
-- Run in Supabase SQL Editor. UUIDs are generated by pgcrypto (available by default on Supabase).
create extension if not exists pgcrypto;

create type public.account_role as enum ('customer','seller','admin');
create type public.seller_status as enum ('pending','approved','rejected','suspended');
create type public.product_status as enum ('draft','active','archived');
create type public.order_status as enum ('pending','confirmed','processing','shipped','delivered','cancelled','refunded');
create type public.payment_method as enum ('cod','online');
create type public.payment_status as enum ('unpaid','pending','paid','failed','refunded');

create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  full_name text,
  phone text unique,
  role public.account_role not null default 'customer',
  preferred_locale text not null default 'bn' check (preferred_locale in ('bn','en')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.sellers (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null unique references public.profiles(id) on delete restrict,
  store_name text not null,
  slug text not null unique,
  description text,
  status public.seller_status not null default 'pending',
  commission_percent numeric(5,2) not null default 8.00 check (commission_percent between 0 and 100),
  created_at timestamptz not null default now()
);

create table public.categories (
  id uuid primary key default gen_random_uuid(),
  parent_id uuid references public.categories(id) on delete set null,
  name_en text not null,
  name_bn text not null,
  slug text not null unique,
  is_active boolean not null default true,
  sort_order int not null default 0
);

create table public.products (
  id uuid primary key default gen_random_uuid(),
  seller_id uuid not null references public.sellers(id) on delete restrict,
  category_id uuid references public.categories(id) on delete set null,
  name_en text not null,
  name_bn text,
  slug text not null unique,
  description text,
  price_bdt numeric(12,2) not null check (price_bdt >= 0),
  compare_at_price_bdt numeric(12,2) check (compare_at_price_bdt is null or compare_at_price_bdt >= price_bdt),
  stock_quantity integer not null default 0 check (stock_quantity >= 0),
  status public.product_status not null default 'draft',
  image_url text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index products_active_category_idx on public.products(category_id, created_at desc) where status='active';
create index products_seller_idx on public.products(seller_id, created_at desc);
create index products_search_idx on public.products using gin (to_tsvector('simple', coalesce(name_en,'') || ' ' || coalesce(name_bn,'') || ' ' || coalesce(description,'')));

create table public.product_variants (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products(id) on delete cascade,
  sku text unique,
  label text not null,
  price_delta_bdt numeric(12,2) not null default 0,
  stock_quantity integer not null default 0 check (stock_quantity >= 0)
);

create table public.addresses (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  recipient_name text not null,
  phone text not null,
  address_line text not null,
  area text,
  city text not null,
  postal_code text,
  country_code char(2) not null default 'BD',
  is_default boolean not null default false,
  created_at timestamptz not null default now()
);

create table public.orders (
  id uuid primary key default gen_random_uuid(),
  order_number text not null unique default ('SH-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),
  customer_id uuid not null references public.profiles(id) on delete restrict,
  address_snapshot jsonb not null,
  subtotal_bdt numeric(12,2) not null check (subtotal_bdt >= 0),
  delivery_fee_bdt numeric(12,2) not null default 0 check (delivery_fee_bdt >= 0),
  total_bdt numeric(12,2) not null check (total_bdt >= 0),
  payment_method public.payment_method not null default 'cod',
  payment_status public.payment_status not null default 'unpaid',
  status public.order_status not null default 'pending',
  created_at timestamptz not null default now()
);

create table public.order_items (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders(id) on delete cascade,
  product_id uuid references public.products(id) on delete set null,
  seller_id uuid not null references public.sellers(id) on delete restrict,
  product_name_snapshot text not null,
  unit_price_bdt numeric(12,2) not null check (unit_price_bdt >= 0),
  quantity integer not null check (quantity > 0),
  line_total_bdt numeric(12,2) not null check (line_total_bdt >= 0)
);

create table public.reviews (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products(id) on delete cascade,
  customer_id uuid not null references public.profiles(id) on delete cascade,
  order_id uuid references public.orders(id) on delete set null,
  rating int not null check (rating between 1 and 5),
  body text,
  created_at timestamptz not null default now(),
  unique(product_id, customer_id, order_id)
);

create table public.wishlists (
  user_id uuid not null references public.profiles(id) on delete cascade,
  product_id uuid not null references public.products(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key(user_id, product_id)
);

create or replace function public.is_admin()
returns boolean language sql stable security definer set search_path=public
as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;

create or replace function public.owns_seller(target_seller uuid)
returns boolean language sql stable security definer set search_path=public
as $$ select exists(select 1 from public.sellers where id=target_seller and owner_id=auth.uid()); $$;

-- Create a customer profile when an auth account is registered.
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path=public
as $$
begin
  insert into public.profiles(id, full_name)
  values(new.id, coalesce(new.raw_user_meta_data->>'full_name',''));
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users
for each row execute procedure public.handle_new_user();

alter table public.profiles enable row level security;
alter table public.sellers enable row level security;
alter table public.categories enable row level security;
alter table public.products enable row level security;
alter table public.product_variants enable row level security;
alter table public.addresses enable row level security;
alter table public.orders enable row level security;
alter table public.order_items enable row level security;
alter table public.reviews enable row level security;
alter table public.wishlists enable row level security;

create policy "profiles read own or admin" on public.profiles for select to authenticated using (id=auth.uid() or public.is_admin());
create policy "profiles update own or admin" on public.profiles for update to authenticated using (id=auth.uid() or public.is_admin()) with check (id=auth.uid() or public.is_admin());

create policy "approved sellers public" on public.sellers for select using (status='approved' or owner_id=auth.uid() or public.is_admin());
create policy "seller owner creates own store" on public.sellers for insert to authenticated with check (owner_id=auth.uid() and status='pending');
create policy "seller owner updates own pending store" on public.sellers for update to authenticated using (owner_id=auth.uid() or public.is_admin()) with check (owner_id=auth.uid() or public.is_admin());

create policy "active categories public" on public.categories for select using (is_active or public.is_admin());
create policy "admin manages categories" on public.categories for all to authenticated using (public.is_admin()) with check (public.is_admin());

create policy "active products public" on public.products for select using (status='active' or public.owns_seller(seller_id) or public.is_admin());
create policy "seller manages own products" on public.products for insert to authenticated with check (public.owns_seller(seller_id));
create policy "seller updates own products" on public.products for update to authenticated using (public.owns_seller(seller_id) or public.is_admin()) with check (public.owns_seller(seller_id) or public.is_admin());
create policy "seller deletes own products" on public.products for delete to authenticated using (public.owns_seller(seller_id) or public.is_admin());

create policy "variants follow visible product" on public.product_variants for select using (
  exists(select 1 from public.products p where p.id=product_id and (p.status='active' or public.owns_seller(p.seller_id) or public.is_admin()))
);
create policy "seller manages own variants" on public.product_variants for all to authenticated using (
  exists(select 1 from public.products p where p.id=product_id and (public.owns_seller(p.seller_id) or public.is_admin()))
) with check (
  exists(select 1 from public.products p where p.id=product_id and (public.owns_seller(p.seller_id) or public.is_admin()))
);

create policy "users manage own addresses" on public.addresses for all to authenticated using (user_id=auth.uid() or public.is_admin()) with check (user_id=auth.uid() or public.is_admin());
create policy "customers read own orders" on public.orders for select to authenticated using (customer_id=auth.uid() or public.is_admin());
create policy "customers create own orders" on public.orders for insert to authenticated with check (customer_id=auth.uid());
create policy "seller sees own order items" on public.order_items for select to authenticated using (public.owns_seller(seller_id) or public.is_admin() or exists(select 1 from public.orders o where o.id=order_id and o.customer_id=auth.uid()));
create policy "customer reads own order items" on public.order_items for select to authenticated using (exists(select 1 from public.orders o where o.id=order_id and o.customer_id=auth.uid()) or public.is_admin());
create policy "verified customer reviews" on public.reviews for select using (true);
create policy "customer creates own review" on public.reviews for insert to authenticated with check (customer_id=auth.uid() and exists(select 1 from public.orders o where o.id=order_id and o.customer_id=auth.uid() and o.status='delivered'));
create policy "customer manages own wishlist" on public.wishlists for all to authenticated using (user_id=auth.uid()) with check (user_id=auth.uid());

grant usage on schema public to anon, authenticated;
grant select on public.categories, public.products, public.sellers, public.product_variants, public.reviews to anon, authenticated;
grant select, insert, update on public.profiles to authenticated;
grant select, insert, update, delete on public.addresses, public.wishlists to authenticated;
grant select, insert on public.orders to authenticated;
grant select on public.order_items to authenticated;
grant select, insert on public.reviews to authenticated;
